 if(v[2]>max){const f=max/v[2];v[0]+=v[2]*(1-f)/2;v[1]+=v[3]*(1-f)/2;v[2]*=f;v[3]*=f}if(v[2]<min){const f=min/v[2];v[0]+=v[2]*(1-f)/2;v[1]+=v[3]*(1-f)/2;v[2]*=f;v[3]*=f}
